SELECT id, api_code, mobile_digest, send_date
FROM b_haier_colliding_data_log
WHERE sync_status = 1
  AND api_code = #{apiCode,jdbcType=VARCHAR}
  AND send_date = #{sendDate,jdbcType=INTEGER}
  AND result = 1
  AND status = 2
order by id LIMIT 2000;

